if(isset($_POST['simpan'])){$username=trim($_POST['username']??'');$nama=trim($_POST['nama']??'');$password=(string)($_POST['password']??'');$peran=$_POST['peran']??'user';if($username===''||$nama===''||$password==='')$error='Semua data wajib diisi.';elseif(strlen($password)<6)$error='Password minimal 6 karakter.';elseif(!in_array($peran,['admin','user'],true))$error='Peran tidak valid.';else{$c=mysqli_prepare($con,'SELECT id_pengguna FROM tbl_pengguna WHERE username=? LIMIT 1');mysqli_stmt_bind_param($c,'s',$username);mysqli_stmt_execute($c);mysqli_stmt_store_result($c);$ada=mysqli_stmt_num_rows($c)>0;mysqli_stmt_close($c);if($ada)$error='Username sudah digunakan.';else{$hash=password_hash($password,PASSWORD_DEFAULT);$s=mysqli_prepare($con,'INSERT INTO tbl_pengguna(username,password,nama,peran) VALUES(?,?,?,?)');mysqli_stmt_bind_param($s,'ssss',$username,$hash,$nama,$peran);if(mysqli_stmt_execute($s)){mysqli_stmt_close($s);header('Location: index.php?pesan=tambah');exit;} $error='Gagal menyimpan pengguna.';mysqli_stmt_close($s);}}}
